def _drain(self, remaining: int) -> None:
    """Discard up to a bounded amount of an oversized declared body.

    Closing the connection while the client's already-sent bytes
    sit unread can surface to the client as a reset rather than the
    error response. Draining a capped amount first lets the close
    be clean without reading an attacker-declared huge length in
    full.
    """

    remaining = min(remaining, MAX_BODY_BYTES * 4)
    while remaining > 0:
        chunk = self.rfile.read(min(remaining, 8192))
        if not chunk:
            break
        remaining -= len(chunk)

