input.command:
cd "maintenance/inputs/s01-batch-inventory" && python -c "
import re, json, csv

def parse_md(path):
    with open(path, encoding='utf-8') as f:
        text = f.read()
    out = {}
    pattern = re.compile(
        r'\*\*(audit-route-s01-t04-\d+)\*\* \| System: ([\w-]+) \| Status: ([\w-]+) \| Evidence: (.*)'
    )
    for line in text.splitlines():
        m = pattern.search(line)
        if m:
            case, system, status, note = m.groups()
            out[case] = (system, status, note)
    return out

def parse_jsonl(path):
    out = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if line:
                rec = json.loads(line)
                out[rec['case']] = (rec['system'], rec['status'], rec['note'])
    return out

def parse_csv(path):
    out = {}
    with open(path, encoding='utf-8', newline='') as f:
        for row in csv.DictReader(f):
            out[row['case']] = (row['system'], row['status'], row['note'])
    return out

def parse_yaml(path):
    with open(path, encoding='utf-8') as f:
        text = f.read()
    out = {}
    blocks = re.findall(
        r'- case: (audit-route-s01-t04-\d+)\s*\n\s*system: ([\w-]+)\s*\n\s*status: ([\w-]+)\s*\n\s*note: \"(.*?)\"',
        text
    )
    for case, system, status, note in blocks:
        out[case] = (system, status, note)
    return out

md = parse_md('audit-route-s01-t04-evidence-01.md')
jsonl = parse_jsonl('audit-route-s01-t04-evidence-02.jsonl')
csvd = parse_csv('audit-route-s01-t04-evidence-03.csv')
yaml = parse_yaml('audit-route-s01-t04-evidence-04.yaml')

print('parsed counts -> md:', len(md), 'jsonl:', len(jsonl), 'csv:', len(csvd), 'yaml:', len(yaml))

sources = {'md': md, 'jsonl': jsonl, 'csv': csvd, 'yaml': yaml}
common = set(md) & set(jsonl) & set(csvd) & set(yaml)
print('cases common to all four files:', len(common))

mismatches = []
for case in sorted(common):
    values = {name: src[case] for name, src in sources.items()}
    if len(set(values.values())) > 1:
        mismatches.append((case, values))

print('mismatches among common cases:', len(mismatches))
for case, values in mismatches[:10]:
    print(case, values)
"

