import re, json, csv

def parse_md(path):
    with open(path, encoding='utf-8') as f:
        text = f.read()
    out = {}
    pattern = re.compile(
        r'\*\*(audit-route-s01-t05-\d+)\*\* \| System: ([\w-]+) \| Status: ([\w-]+) \| Evidence: (.*)'
    )
    for line in text.splitlines():
        m = pattern.search(line)
        if m:
            case, system, status, note = m.groups()
            out[case] = (system, status, note)
    return out

def parse_jsonl(path):
    out = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if line:
                rec = json.loads(line)
                out[rec['case']] = (rec['system'], rec['status'], rec['note'])
    return out

def parse_csv(path):
    out = {}
    with open(path, encoding='utf-8', newline='') as f:
        for row in csv.DictReader(f):
            out[row['case']] = (row['system'], row['status'], row['note'])
    return out

def parse_yaml(path):
    with open(path, encoding='utf-8') as f:
        text = f.read()
    out = {}
    blocks = re.findall(
        r'- case: (audit-route-s01-t05-\d+)\s*\n\s*system: ([\w-]+)\s*\n\s*status: ([\w-]+)\s*\n\s*note: \"(.*?)\"',
        text
    )
    for case, system, status, note in blocks:
        out[case] = (system, status, note)
    return out

md = parse_md('audit-route-s01-t05-evidence-01.md')
jsonl = parse_jsonl('audit-route-s01-t05-evidence-02.jsonl')
csvd = parse_csv('audit-route-s01-t05-evidence-03.csv')
yaml = parse_yaml('audit-route-s01-t05-evidence-04.yaml')

print('parsed counts -> md:', len(md), 'jsonl:', len(jsonl), 'csv:', len(csvd), 'yaml:', len(yaml))

def rng(s):
    nums = sorted(int(c.split('-')[-1]) for c in s)
    return (f'{nums[0]:06d}-{nums[-1]:06d}', len(nums), nums == list(range(nums[0], nums[-1]+1))) if nums else ('none', 0, True)

for name, src in [('md', md), ('jsonl', jsonl), ('csv', csvd), ('yaml', yaml)]:
    r = rng(set(src.keys()))
    print(name, 'range:', r[0], 'count:', r[1], 'sequential:', r[2])

sets = {'md': set(md), 'jsonl': set(jsonl), 'csv': set(csvd), 'yaml': set(yaml)}
names = list(sets.keys())
for i in range(len(names)):
    for j in range(len(names)):
        if i != j:
            diff = sets[names[i]] - sets[names[j]]
            if diff:
                print(f'{names[i]} - {names[j]}:', rng(diff))

common = set(md) & set(jsonl) & set(csvd) & set(yaml)
print('common to all four:', len(common))
sources = {'md': md, 'jsonl': jsonl, 'csv': csvd, 'yaml': yaml}
mismatches = []
for case in sorted(common):
    values = {name: src[case] for name, src in sources.items()}
    if len(set(values.values())) > 1:
        mismatches.append((case, values))
print('mismatches among common cases:', len(mismatches))
for case, values in mismatches[:10]:
    print(case, values)
"

