"""Storage-independent audit log service interface.

``AuditLogService`` is the contract every storage backend (in-memory, a
file, a database) must satisfy; callers depend on this interface rather than
on a specific backend so the storage mechanism can change without touching
callers. ``InMemoryAuditLogService`` is a reference implementation used by
the contract tests and by callers that do not need durability.

Every implementation must preserve two invariants: recorded events are
append-only (never removed, rewritten, or reordered), and an event's id is
always derived from its own canonical content, never accepted verbatim from
a caller.
"""

from __future__ import annotations

from abc import ABC, abstractmethod
from collections.abc import Iterable
from typing import Any

from .models import ArchiveCandidate, AuditEvent, ImportManifest, content_digest


class AuditLogService(ABC):
    """Append-only audit trail with interrupted-archive-import support."""

    @abstractmethod
    def record(
        self,
        actor: str,
        action: str,
        outcome: str,
        recorded_at: str,
        metadata: dict[str, Any] | None = None,
    ) -> AuditEvent:
        """Append one event and return it with its assigned sequence and id."""

    @abstractmethod
    def events(self) -> tuple[AuditEvent, ...]:
        """Return every recorded event, in append order."""

    @abstractmethod
    def find(
        self, *, actor: str | None = None, action: str | None = None
    ) -> tuple[AuditEvent, ...]:
        """Return recorded events matching the given filters, in append order."""

    @abstractmethod
    def verify(self) -> tuple[AuditEvent, ...]:
        """Return recorded events whose current content no longer matches their id."""

    @abstractmethod
    def import_archive(
        self, manifest: ImportManifest, candidates: Iterable[ArchiveCandidate]
    ) -> tuple[ImportManifest, tuple[AuditEvent, ...]]:
        """Resume an interrupted archive import.

        Each candidate's canonical content id is recomputed here rather than
        trusted from the archive. A candidate whose content id is already in
        ``manifest.imported_content_ids`` or already recorded is skipped, so
        re-running an interrupted import from an earlier offset cannot
        duplicate an event. Returns the advanced manifest and the events
        newly appended.
        """


class InMemoryAuditLogService(AuditLogService):
    """Reference ``AuditLogService`` implementation held in memory."""

    def __init__(self) -> None:
        self._events: list[AuditEvent] = []

    def record(
        self,
        actor: str,
        action: str,
        outcome: str,
        recorded_at: str,
        metadata: dict[str, Any] | None = None,
    ) -> AuditEvent:
        event = AuditEvent(
            event_id=content_digest(actor, action, outcome, recorded_at),
            sequence=len(self._events) + 1,
            actor=actor,
            action=action,
            outcome=outcome,
            recorded_at=recorded_at,
            metadata=dict(metadata or {}),
        )
        self._events.append(event)
        return event

    def events(self) -> tuple[AuditEvent, ...]:
        return tuple(self._events)

    def find(
        self, *, actor: str | None = None, action: str | None = None
    ) -> tuple[AuditEvent, ...]:
        return tuple(
            event
            for event in self._events
            if (actor is None or event.actor == actor)
            and (action is None or event.action == action)
        )

    def verify(self) -> tuple[AuditEvent, ...]:
        return tuple(event for event in self._events if event.event_id != event.recomputed_id())

    def import_archive(
        self, manifest: ImportManifest, candidates: Iterable[ArchiveCandidate]
    ) -> tuple[ImportManifest, tuple[AuditEvent, ...]]:
        known_ids = set(manifest.imported_content_ids) | {event.event_id for event in self._events}
        appended: list[AuditEvent] = []
        newly_imported: list[str] = []
        offset = manifest.resume_offset

        for candidate in candidates:
            offset += 1
            content_id = candidate.content_id()
            if content_id in known_ids:
                continue
            event = AuditEvent(
                event_id=content_id,
                sequence=len(self._events) + 1,
                actor=candidate.actor,
                action=candidate.action,
                outcome=candidate.outcome,
                recorded_at=candidate.recorded_at,
                metadata={"source_ref": candidate.source_ref} if candidate.source_ref else {},
            )
            self._events.append(event)
            appended.append(event)
            newly_imported.append(content_id)
            known_ids.add(content_id)

        advanced = manifest.advanced(offset, newly_imported)
        return advanced, tuple(appended)

"""Request-path helpers shared by authentication and dispatch.

Versioned routes and proxy spellings should pass through one helper so a
documented path and a harmless alternate spelling reach the same decision.
"""
from __future__ import annotations

from urllib.parse import unquote


def canonical_path(raw_path: str) -> str:
    """Compatibility spelling: decode, collapse slashes, drop one trailing slash."""

    path = unquote(raw_path)
    while "//" in path:
        path = path.replace("//", "/")
    if len(path) > 1:
        path = path.rstrip("/")
    return path or "/"


def auth_path(raw_path: str) -> str:
    """Path used to look up the route table before reading a body."""

    # Look up the route using the same path spelling the rest of the service uses.
    return canonical_path(raw_path)


def dispatch_path(raw_path: str) -> str:
    """Path handed to the handler after the route decision."""

    # Hand the handler the same path the route lookup used.
    return auth_path(raw_path)

"""Focused tests for the strict event and import-manifest models."""

from __future__ import annotations

import unittest

from auditlog.models import ArchiveCandidate, AuditEvent, ImportManifest, content_digest


class AuditEventValidationTests(unittest.TestCase):
    def test_rejects_empty_identifying_fields(self) -> None:
        for field_name in ("actor", "action", "outcome", "recorded_at"):
            kwargs = dict(
                event_id="x", sequence=1, actor="a", action="b", outcome="c", recorded_at="d"
            )
            kwargs[field_name] = ""
            with self.assertRaises(ValueError):
                AuditEvent(**kwargs)

    def test_rejects_non_positive_sequence(self) -> None:
        with self.assertRaises(ValueError):
            AuditEvent("id", 0, "a", "b", "c", "d")
        with self.assertRaises(ValueError):
            AuditEvent("id", -1, "a", "b", "c", "d")

    def test_rejects_non_dict_metadata(self) -> None:
        with self.assertRaises(ValueError):
            AuditEvent("id", 1, "a", "b", "c", "d", metadata="not-a-dict")  # type: ignore[arg-type]

    def test_metadata_is_not_part_of_recomputed_identity(self) -> None:
        event = AuditEvent(
            content_digest("a", "b", "c", "d"), 1, "a", "b", "c", "d", metadata={"note": "x"}
        )
        same_content_other_metadata = AuditEvent(
            event.event_id, 1, "a", "b", "c", "d", metadata={"note": "different"}
        )
        self.assertEqual(event.recomputed_id(), same_content_other_metadata.recomputed_id())


class ArchiveCandidateTests(unittest.TestCase):
    def test_rejects_empty_identifying_fields(self) -> None:
        for field_name in ("actor", "action", "outcome", "recorded_at"):
            kwargs = dict(actor="a", action="b", outcome="c", recorded_at="d")
            kwargs[field_name] = ""
            with self.assertRaises(ValueError):
                ArchiveCandidate(**kwargs)

    def test_content_id_matches_canonical_digest(self) -> None:
        candidate = ArchiveCandidate("a", "b", "c", "d", source_ref="arch-1")
        self.assertEqual(candidate.content_id(), content_digest("a", "b", "c", "d"))

    def test_source_ref_is_descriptive_and_does_not_affect_content_id(self) -> None:
        one = ArchiveCandidate("a", "b", "c", "d", source_ref="arch-1")
        other = ArchiveCandidate("a", "b", "c", "d", source_ref="arch-2")
        self.assertEqual(one.content_id(), other.content_id())


class ImportManifestTests(unittest.TestCase):
    def test_rejects_empty_batch_id_or_archive_ref(self) -> None:
        with self.assertRaises(ValueError):
            ImportManifest(batch_id="", archive_ref="ref")
        with self.assertRaises(ValueError):
            ImportManifest(batch_id="batch", archive_ref="")

    def test_rejects_negative_resume_offset(self) -> None:
        with self.assertRaises(ValueError):
            ImportManifest(batch_id="batch", archive_ref="ref", resume_offset=-1)

    def test_advanced_merges_ids_without_mutating_original(self) -> None:
        original = ImportManifest(batch_id="batch", archive_ref="ref")
        advanced = original.advanced(2, ["id-1", "id-2"])
        self.assertEqual(original.resume_offset, 0)
        self.assertEqual(original.imported_content_ids, frozenset())
        self.assertEqual(advanced.resume_offset, 2)
        self.assertEqual(advanced.imported_content_ids, frozenset({"id-1", "id-2"}))

    def test_advanced_rejects_moving_offset_backward(self) -> None:
        manifest = ImportManifest(batch_id="batch", archive_ref="ref", resume_offset=5)
        with self.assertRaises(ValueError):
            manifest.advanced(4, [])


class InterruptedImportScenarioTests(unittest.TestCase):
    """Grounded in the seed scenario: an import restarts mid-batch."""

    def test_before_and_after_restart_events_have_different_content_ids(self) -> None:
        before_restart = ArchiveCandidate(
            actor="operator:mina",
            action="archive.import",
            outcome="allowed",
            recorded_at="2026-08-11T09:30:00+00:00",
            source_ref="offset-1",
        )
        after_restart = ArchiveCandidate(
            actor="operator:mina",
            action="archive.import",
            outcome="allowed",
            recorded_at="2026-08-11T09:30:07+00:00",
            source_ref="offset-2",
        )
        self.assertNotEqual(before_restart.content_id(), after_restart.content_id())

    def test_control_event_from_a_different_actor_is_a_third_distinct_id(self) -> None:
        mina_event = ArchiveCandidate(
            "operator:mina", "archive.import", "allowed", "2026-08-11T09:30:00+00:00"
        )
        control_event = ArchiveCandidate(
            "operator:sven", "archive.import", "allowed", "2026-08-11T09:31:00+00:00"
        )
        self.assertNotEqual(mina_event.content_id(), control_event.content_id())


if __name__ == "__main__":
    unittest.main()

