import json, csv, re

def parse_md(path):
    rows = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line.startswith('- **'):
                continue
            m = re.match(r'- \*\*(?P<case>[^*]+)\*\* \| System: (?P<system>[^|]+) \| Status: (?P<status>[^|]+) \| Evidence: (?P<note>.+)', line)
            if m:
                rows[m.group('case')] = (m.group('system').strip(), m.group('status').strip(), m.group('note').strip())
    return rows

def parse_jsonl(path):
    rows = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            rows[obj['case']] = (obj['system'], obj['status'], obj['note'])
    return rows

def parse_csv(path):
    rows = {}
    with open(path, encoding='utf-8', newline='') as f:
        for obj in csv.DictReader(f):
            rows[obj['case']] = (obj['system'], obj['status'], obj['note'])
    return rows

def parse_yaml(path):
    rows = {}
    case = system = status = None
    note_lines = []
    with open(path, encoding='utf-8') as f:
        for raw in f:
            line = raw.rstrip('\r\n')
            if line.startswith('- case:'):
                if case is not None:
                    rows[case] = (system, status, ' '.join(note_lines))
                case = line.split(':', 1)[1].strip()
                system = status = None
                note_lines = []
            elif line.strip().startswith('system:'):
                system = line.split(':', 1)[1].strip()
            elif line.strip().startswith('status:'):
                status = line.split(':', 1)[1].strip()
            elif line.strip().startswith('note:'):
                note = line.split(':', 1)[1].strip()
                note_lines.append(note.strip('\"'))
        if case is not None:
            rows[case] = (system, status, ' '.join(note_lines))
    return rows

md = parse_md('audit-route-s01-t11-evidence-01.md')
jl = parse_jsonl('audit-route-s01-t11-evidence-02.jsonl')
cv = parse_csv('audit-route-s01-t11-evidence-03.csv')
ym = parse_yaml('audit-route-s01-t11-evidence-04.yaml')

print('md cases:', len(md), 'jsonl cases:', len(jl), 'csv cases:', len(cv), 'yaml cases:', len(ym))

common = set(md) & set(jl) & set(cv) & set(ym)
print('common cases across all 4:', len(common))

mismatches = []
for c in sorted(common):
    vals = {'md': md[c], 'jsonl': jl[c], 'csv': cv[c], 'yaml': ym[c]}
    if len(set(vals.values())) > 1:
        mismatches.append((c, vals))
print('mismatches among common cases:', len(mismatches))

print('md == yaml over common md/yaml set?', all(md[c]==ym[c] for c in set(md)&set(ym)))
print('cases in md not in jsonl: count', len(set(md)-set(jl)))
print('cases in csv not in md: count', len(set(cv)-set(md)))
print('cases in csv not in jsonl: count', len(set(cv)-set(jl)))
print('cases in md not in csv: count', len(set(md)-set(cv)))
print('cases in yaml not in csv: count', len(set(ym)-set(cv)))
