import re, json, csv

def parse_md(path):
    out = {}
    pat = re.compile(r'\*\*(audit-route-s01-t14-\d{6})\*\* \| System: (\S+) \| Status: (\S+) \| Evidence: (.*)$')
    with open(path, encoding='utf-8') as f:
        for line in f:
            m = pat.search(line.rstrip('\n'))
            if m:
                case, system, status, note = m.groups()
                out[case] = {'system': system, 'status': status, 'note': note}
    return out

def parse_jsonl(path):
    out = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            out[obj['case']] = {'system': obj['system'], 'status': obj['status'], 'note': obj['note']}
    return out

def parse_csv(path):
    out = {}
    with open(path, encoding='utf-8', newline='') as f:
        for row in csv.DictReader(f):
            out[row['case']] = {'system': row['system'], 'status': row['status'], 'note': row['note']}
    return out

def parse_yaml(path):
    out = {}
    case = None
    entry = {}
    with open(path, encoding='utf-8') as f:
        for raw in f:
            line = raw.rstrip('\n')
            if line.startswith('- case:'):
                if case:
                    out[case] = entry
                case = line.split(':', 1)[1].strip()
                entry = {}
            elif line.strip().startswith('system:'):
                entry['system'] = line.split(':', 1)[1].strip()
            elif line.strip().startswith('status:'):
                entry['status'] = line.split(':', 1)[1].strip()
            elif line.strip().startswith('note:'):
                entry['note'] = line.split(':', 1)[1].strip().strip('\"')
        if case:
            out[case] = entry
    return out

md = parse_md('audit-route-s01-t14-evidence-01.md')
jsonl = parse_jsonl('audit-route-s01-t14-evidence-02.jsonl')
csvd = parse_csv('audit-route-s01-t14-evidence-03.csv')
yaml = parse_yaml('audit-route-s01-t14-evidence-04.yaml')

def case_num(c):
    return int(c.rsplit('-',1)[1])

for name, d in [('md', md), ('jsonl', jsonl), ('csv', csvd), ('yaml', yaml)]:
    nums = sorted(case_num(c) for c in d)
    print(name, 'count=', len(d), 'min=', nums[0], 'max=', nums[-1], 'contiguous=', nums == list(range(nums[0], nums[-1]+1)))

print()
print('md == yaml (same keys and values)?', md == yaml)

common = set(md) & set(jsonl) & set(csvd) & set(yaml)
print('common cases across all four:', len(common))

mismatches = []
for c in sorted(common, key=case_num):
    vals = {'md': md[c], 'jsonl': jsonl[c], 'csv': csvd[c], 'yaml': yaml[c]}
    if not (vals['md'] == vals['jsonl'] == vals['csv'] == vals['yaml']):
        mismatches.append((c, vals))
print('field mismatches among common cases:', len(mismatches))
for m in mismatches[:10]:
    print(m)

print()
print('cases in csv not in md:', sorted(set(csvd)-set(md), key=case_num))
print('cases in md not in jsonl:', sorted(set(md)-set(jsonl), key=case_num))
print('cases in md not in csv:', sorted(set(md)-set(csvd), key=case_num))
print('cases in yaml not in md:', sorted(set(yaml)-set(md), key=case_num))
print('cases in jsonl not in md:', sorted(set(jsonl)-set(md), key=case_num))
